     1	namespace Atm.Tests;
     2	
     3	/// <summary>Parcourt une large part du domaine et compare à un modèle de référence écrit indépendamment.</summary>
     4	public class DomainSweepTests
     5	{
     6	    private static readonly Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
     7	
     8	    private static IEnumerable<NoteCounts> AllStocks()
     9	    {
    10	        for (var f = 0; f <= 5; f++)
    11	            for (var t = 0; t <= 5; t++)
    12	                for (var c = 0; c <= 5; c++)
    13	                    yield return new NoteCounts(f, t, c);
    14	    }
    15	
    16	    private static AtmResult ExpectedWithdraw(AccountState a, NoteCounts stock, Denomination? jam, int amount)
    17	    {
    18	        AtmResult Refused(AtmStatus s) => new(s, NoteCounts.None, 0, a);
    19	
    20	        if (amount <= 0 || amount % 10 != 0) return Refused(AtmStatus.InvalidAmount);
    21	        if (a.WithdrawnToday + amount > 200) return Refused(AtmStatus.DailyLimitExceeded);
    22	        var fee = amount > 100 ? 5 : 0;
    23	        if (amount + fee > a.Balance) return Refused(AtmStatus.InsufficientFunds);
    24	
    25	        var usable = new NoteCounts(
    26	            jam == Denomination.Fifty ? 0 : stock.Fifties,
    27	            jam == Denomination.Twenty ? 0 : stock.Twenties,
    28	            jam == Denomination.Ten ? 0 : stock.Tens);
    29	
    30	        var candidates = (
    31	            from f in Enumerable.Range(0, usable.Fifties + 1)
    32	            from t in Enumerable.Range(0, usable.Twenties + 1)
    33	            from c in Enumerable.Range(0, usable.Tens + 1)
    34	            let n = new NoteCounts(f, t, c)
    35	            where n.Value == amount
    36	            orderby n.Total
    37	            select n).ToList();
    38	
    39	        if (candidates.Count == 0) return Refused(AtmStatus.CannotDispense);
    40	        if (candidates.Count > 1) Assert.NotEqual(candidates[0].Total, candidates[1].Total); // unicité annoncée
    41	
    42	        return new AtmResult(AtmStatus.Ok, candidates[0], fee,
    43	            new AccountState(a.Balance - amount - fee, a.WithdrawnToday + amount));
    44	    }
    45	
    46	    [Fact]
    47	    public void Withdraw_matches_reference_model()
    48	    {
    49	        int[] amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
    50	        AccountState[] accounts = [new(250, 0), new(115, 0), new(100, 50), new(0, 0), new(250, 190), new(205, 0)];
    51	
    52	        foreach (var stock in AllStocks())
    53	        foreach (var jam in Jams)
    54	        foreach (var amount in amounts)
    55	        foreach (var account in accounts)
    56	        {
    57	            var dispenser = new RecordingDispenser(stock, jam);
    58	            var actual = new CashMachine(dispenser).Execute(account, new Operation.Withdraw(amount));
    59	            var expected = ExpectedWithdraw(account, stock, jam, amount);
    60	
    61	            Assert.Equal(expected, actual);
    62	            Assert.Equal(stock - actual.Notes, dispenser.Stock);
    63	            Assert.All(dispenser.DispenseCalls, p => Assert.InRange(p.Total, 1, 4));
    64	        }
    65	    }
    66	
    67	    [Fact]
    68	    public void Deposit_matches_reference_model()
    69	    {
    70	        var account = new AccountState(55, 70);
    71	
    72	        foreach (var stock in AllStocks())
    73	        foreach (var jam in Jams)
    74	        for (var mask = 0; mask < 8; mask++)
    75	        {
    76	            var notes = new NoteCounts(mask & 1, (mask >> 1) & 1, (mask >> 2) & 1);
    77	            var dispenser = new MoneyDispenser(stock, jam);
    78	            var actual = new CashMachine(dispenser).Execute(account, new Operation.Deposit(notes));
    79	
    80	            var after = stock + notes;
    81	            var expectedStatus =
    82	                notes.Total == 0 ? AtmStatus.InvalidAmount
    83	                : jam is { } j && notes.Of(j) > 0 ? AtmStatus.CassetteJammed
    84	                : after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5 ? AtmStatus.CassetteFull
    85	                : AtmStatus.Ok;
    86	
    87	            Assert.Equal(expectedStatus, actual.Status);
    88	            Assert.Equal(NoteCounts.None, actual.Notes);
    89	            Assert.Equal(0, actual.Fee);
    90	            if (expectedStatus == AtmStatus.Ok)
    91	            {
    92	                Assert.Equal(account with { Balance = account.Balance + notes.Value }, actual.Account);
    93	                Assert.Equal(after, dispenser.Stock);
    94	            }
    95	            else
    96	            {
    97	                Assert.Equal(account, actual.Account);
    98	                Assert.Equal(stock, dispenser.Stock);
    99	            }
   100	        }
   101	    }
   102	}
