     3	/// <summary>Enveloppe le vrai module, enregistre les appels et peut simuler une panne.</summary>
     4	internal sealed class RecordingDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
     5	{
     6	    private readonly MoneyDispenser _inner = new(stock, jammed);
     7	
     8	    public List<NoteCounts> DispenseCalls { get; } = [];
     9	    public List<NoteCounts> LoadCalls { get; } = [];
    10	
    11	    /// <summary>Numéro (à partir de 1) de l'appel à <c>Dispense</c> qui échoue, ou <c>null</c>.</summary>
    12	    public int? FailDispenseOnCall { get; init; }
    13	
    14	    public bool FailLoad { get; init; }
    15	
    16	    public NoteCounts Stock => _inner.Stock;
    17	
    18	    public Denomination? Jammed => _inner.Jammed;
    19	
    20	    public bool Dispense(NoteCounts notes)
    21	    {
    22	        DispenseCalls.Add(notes);
    23	        return DispenseCalls.Count != FailDispenseOnCall && _inner.Dispense(notes);
    24	    }
    25	
    26	    public bool Load(NoteCounts notes)
    27	    {
    28	        LoadCalls.Add(notes);
    29	        return !FailLoad && _inner.Load(notes);
    30	    }
    31	}
