     3	public class CashMachineTests
     4	{
     5	    private static Denomination? Jam(int jammed) => jammed == 0 ? null : (Denomination)jammed;
     6	
     7	    private static (AtmResult Result, MoneyDispenser Dispenser) Run(
     8	        int balance, int withdrawn, NoteCounts stock, Denomination? jammed, Operation operation)
     9	    {
    10	        var dispenser = new MoneyDispenser(stock, jammed);
    11	        var result = new CashMachine(dispenser).Execute(new AccountState(balance, withdrawn), operation);
    12	        return (result, dispenser);
    13	    }
    14	
    15	    private static void AssertRefused(AtmResult result, AtmStatus status, AccountState account)
    16	    {
    17	        Assert.Equal(status, result.Status);
    18	        Assert.Equal(NoteCounts.None, result.Notes);
    19	        Assert.Equal(0, result.Fee);
    20	        Assert.Equal(account, result.Account);
    21	    }
    22	
    23	    // ---------- Exemples de la spécification ----------
    24	
    25	    [Theory]
    26	    // solde, retiré, stock 50/20/10, bloquée, montant, billets attendus 50/20/10, frais, solde après, retiré après
    27	    [InlineData(100, 0, 1, 3, 0, 0, 60, 0, 3, 0, 0, 40, 60)]
    28	    [InlineData(100, 0, 1, 1, 1, 0, 80, 1, 1, 1, 0, 20, 80)]
    29	    [InlineData(105, 0, 5, 5, 5, 0, 100, 2, 0, 0, 0, 5, 100)]
    30	    [InlineData(115, 0, 5, 5, 5, 0, 110, 2, 0, 1, 5, 0, 110)]
    31	    [InlineData(250, 0, 2, 2, 0, 50, 40, 0, 2, 0, 0, 210, 40)]
    32	    public void Withdraw_examples_succeed(
    33	        int balance, int withdrawn, int f, int t, int c, int jammed, int amount,
    34	        int ef, int et, int ec, int fee, int balanceAfter, int withdrawnAfter)
    35	    {
    36	        var stock = new NoteCounts(f, t, c);
    37	        var (result, dispenser) = Run(balance, withdrawn, stock, Jam(jammed), new Operation.Withdraw(amount));
    38	
    39	        var expected = new NoteCounts(ef, et, ec);
    40	        Assert.Equal(AtmStatus.Ok, result.Status);
    41	        Assert.Equal(expected, result.Notes);
    42	        Assert.Equal(fee, result.Fee);
    43	        Assert.Equal(new AccountState(balanceAfter, withdrawnAfter), result.Account);
    44	        Assert.Equal(stock - expected, dispenser.Stock);
    45	    }
