    47	    [Theory]
    48	    [InlineData(110, 0, 5, 5, 5, 0, 110, AtmStatus.InsufficientFunds)]
    49	    [InlineData(250, 150, 5, 5, 5, 0, 60, AtmStatus.DailyLimitExceeded)]
    50	    [InlineData(250, 0, 1, 0, 0, 50, 50, AtmStatus.CannotDispense)]
    51	    [InlineData(0, 200, 0, 0, 0, 0, 5, AtmStatus.InvalidAmount)]
    52	    public void Withdraw_examples_are_refused(
    53	        int balance, int withdrawn, int f, int t, int c, int jammed, int amount, AtmStatus status)
    54	    {
    55	        var stock = new NoteCounts(f, t, c);
